package com.farmingpatchadvisor;

import org.junit.Test;

import static org.junit.Assert.assertTrue;
import static org.junit.Assert.assertEquals;

public class FarmingLoadoutTest
{
	@Test
	public void fullRunIncludesMultipleSeedsForMultiSeedPatches()
	{
		int allotments = FarmRunCatalog.patches().stream()
			.filter(patch -> patch.getPatchType() == PatchType.ALLOTMENT)
			.mapToInt(FarmRunPatch::getPatchCount)
			.sum();
		assertTrue(allotments > 1);
		assertTrue(allotments * CropCatalog.recommend(PatchType.ALLOTMENT, 99).getQuantity() > allotments);
	}

	@Test
	public void plantingReducesOnlyTheStillNeededSide()
	{
		assertEquals(30, FarmingLoadout.stableOwnedSeedCount(30, true, 27));
		assertEquals(30, FarmingLoadout.stableOwnedSeedCount(30, true, 24));
		assertEquals(30, FarmingLoadout.stableOwnedSeedCount(27, true, 30));
		assertEquals(24, FarmingLoadout.stableOwnedSeedCount(30, false, 24));
		assertEquals(27, FarmingLoadout.remainingSeedQuantity(10, 1, 3));
		assertEquals(0, FarmingLoadout.remainingSeedQuantity(10, 10, 3));
	}
}

package com.farmingpatchadvisor;

import java.util.EnumSet;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class FarmRunTypeTest
{
	@Test
	public void categorizesEverySupportedPatchType()
	{
		EnumSet<PatchType> categorized = EnumSet.noneOf(PatchType.class);
		for (PatchType patchType : PatchType.values())
		{
			FarmRunType.forPatchType(patchType);
			categorized.add(patchType);
		}
		assertEquals(EnumSet.allOf(PatchType.class), categorized);
	}

	@Test
	public void usesExpectedFarmRunCategories()
	{
		assertEquals(FarmRunType.ALLOTMENT_FLOWER, FarmRunType.forPatchType(PatchType.ALLOTMENT));
		assertEquals(FarmRunType.ALLOTMENT_FLOWER, FarmRunType.forPatchType(PatchType.FLOWER));
		assertEquals(FarmRunType.HERB, FarmRunType.forPatchType(PatchType.HERB));
		assertEquals(FarmRunType.FRUIT_TREE_CALQUAT, FarmRunType.forPatchType(PatchType.CALQUAT));
		assertEquals(FarmRunType.SPECIALTY, FarmRunType.forPatchType(PatchType.SEAWEED));
		assertEquals(FarmRunType.SPECIALTY, FarmRunType.forPatchType(PatchType.ANIMA));
	}

	@Test
	public void magicSecateursOnlyApplyToWikiListedYieldPatches()
	{
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.HERB));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.ALLOTMENT));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.HOPS));
		assertTrue(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.GRAPEVINE));
		assertFalse(FarmingLoadout.isYieldBoostedByMagicSecateurs(PatchType.TREE));
	}

	@Test
	public void usesCorrectCareFlagsForEveryPatchType()
	{
		EnumSet<PatchType> compostAndWater = EnumSet.of(
			PatchType.ALLOTMENT,
			PatchType.FLOWER,
			PatchType.HOPS);
		EnumSet<PatchType> compostOnly = EnumSet.of(
			PatchType.HERB,
			PatchType.BUSH,
			PatchType.TREE,
			PatchType.FRUIT_TREE,
			PatchType.HARDWOOD_TREE,
			PatchType.CACTUS,
			PatchType.MUSHROOM,
			PatchType.BELLADONNA,
			PatchType.CALQUAT,
			PatchType.SPIRIT_TREE,
			PatchType.SEAWEED,
			PatchType.CELASTRUS,
			PatchType.REDWOOD,
			PatchType.CRYSTAL_TREE,
			PatchType.CORAL);
		EnumSet<PatchType> noCareFlags = EnumSet.of(
			PatchType.GRAPEVINE,
			PatchType.HESPORI,
			PatchType.ANIMA);

		EnumSet<PatchType> audited = EnumSet.noneOf(PatchType.class);
		audited.addAll(compostAndWater);
		audited.addAll(compostOnly);
		audited.addAll(noCareFlags);
		assertEquals(EnumSet.allOf(PatchType.class), audited);

		for (PatchType patchType : PatchType.values())
		{
			assertEquals(compostAndWater.contains(patchType), patchType.canBeWatered());
			assertEquals(compostAndWater.contains(patchType) || compostOnly.contains(patchType),
				patchType.usesCompost());
		}
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.time.Duration;
import java.time.Instant;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import net.runelite.api.Point;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class PatchTimerTest
{
	@Test
	public void correctsPersistedHardwoodTimersWithoutChangingOtherEstimates()
	{
		Instant observed = Instant.parse("2026-09-17T00:00:00Z");
		WorldPoint patch = new WorldPoint(1, 2, 0);
		String[] names = {"Teak sapling", "Mahogany sapling", "Camphor sapling",
			"Ironwood sapling", "Rosewood sapling"};
		int[] oldMinutes = {5120, 5760, 5760, 5760, 6400};
		int[] stages = {8, 9, 9, 9, 10};
		for (int i = 0; i < names.length; i++)
		{
			Crop crop = CropCatalog.findByName(PatchType.HARDWOOD_TREE, names[i]);
			PatchTimer planted = new PatchTimer(patch, PatchType.HARDWOOD_TREE, crop,
				observed, observed.plus(Duration.ofMinutes(oldMinutes[i])));
			PatchTimer corrected = PatchTimerManager.correctLegacyHardwoodTimer(planted);
			assertEquals(names[i], observed.plus(CropGrowthTimes.forCrop(crop)), corrected.getReadyAt());
			assertTrue(corrected.isPlantedTimer());

			long oldStageSeconds = (oldMinutes[i] * 60L + stages[i] - 2L) / (stages[i] - 1L);
			PatchTimer inspected = new PatchTimer(patch, PatchType.HARDWOOD_TREE, crop,
				observed, observed.plusSeconds(oldStageSeconds * (stages[i] - 3)), false, 3, stages[i]);
			PatchTimer correctedInspection = PatchTimerManager.correctLegacyHardwoodTimer(inspected);
			assertEquals(names[i], observed.plus(CropGrowthTimes.maximumRemainingAtStage(crop, 3, stages[i])),
				correctedInspection.getReadyAt());
			assertFalse(correctedInspection.isPlantedTimer());
		}

		Crop teak = CropCatalog.findByName(PatchType.HARDWOOD_TREE, "Teak sapling");
		PatchTimer custom = new PatchTimer(patch, PatchType.HARDWOOD_TREE, teak,
			observed, observed.plus(Duration.ofMinutes(4500)));
		assertSame(custom, PatchTimerManager.correctLegacyHardwoodTimer(custom));
	}

	@Test
	public void harvestingRequiresAnEmptyPatchState()
	{
		assertFalse(PatchTimerManager.isEmptyPatchState("Herbs",
			new String[]{"Harvest", "Inspect", "Guide"}));
		assertFalse(PatchTimerManager.isEmptyPatchState("Herb patch",
			new String[]{"Harvest", "Inspect", "Guide"}));
		assertTrue(PatchTimerManager.isEmptyPatchState("Herb patch",
			new String[]{"Inspect", "Guide"}));
		assertTrue(PatchTimerManager.isEmptyPatchState("Allotment",
			new String[]{"Rake", "Inspect", "Guide"}));
		assertFalse(PatchTimerManager.isEmptyPatchState("Dead herbs",
			new String[]{"Clear", "Inspect", "Guide"}));
		assertTrue(PatchTimerManager.hasHarvestAction(new String[]{"Pick-banana", "Inspect"}));
		assertTrue(PatchTimerManager.hasHarvestAction(new String[]{"Harvest", "Inspect"}));
		assertFalse(PatchTimerManager.hasHarvestAction(new String[]{"Inspect", "Clear", null}));
	}

	@Test
	public void keepsHarvestedCivitasCropReadyUntilThePatchIsActuallyEmpty()
	{
		assertTrue(PatchTimerManager.isLiveHarvestTransition("Herbs",
			new String[]{"Clear", "Inspect", "Guide"}));
		assertFalse(PatchTimerManager.isLiveHarvestTransition("Dead herbs",
			new String[]{"Clear", "Inspect", "Guide"}));
		assertFalse(PatchTimerManager.isLiveHarvestTransition("Diseased herbs",
			new String[]{"Cure", "Inspect", "Guide"}));
		assertFalse(PatchTimerManager.isLiveHarvestTransition("Herb patch",
			new String[]{"Inspect", "Guide"}));
	}

	@Test
	public void usesConsistentTimerStateColors()
	{
		Crop potato = CropCatalog.findByName(PatchType.ALLOTMENT, "Potato");
		Instant now = Instant.parse("2026-08-26T00:00:00Z");
		WorldPoint location = new WorldPoint(0, 0, 0);

		PatchTimer growing = new PatchTimer(location, PatchType.ALLOTMENT, potato,
			now, now.plusSeconds(600), true, -1, -1, false, false);
		PatchTimer ready = new PatchTimer(location, PatchType.ALLOTMENT, potato,
			now.minusSeconds(600), now, true, -1, -1, false, false);
		PatchTimer dead = new PatchTimer(location, PatchType.ALLOTMENT, potato,
			now, now.plusSeconds(600), true, -1, -1, true, false);
		PatchTimer diseased = new PatchTimer(location, PatchType.ALLOTMENT, potato,
			now, now.plusSeconds(600), true, -1, -1, false, true);
		PatchTimer picked = new PatchTimer(location, PatchType.ALLOTMENT, potato,
			now, now.plusSeconds(600), true, -1, -1, false, false, false, false, true);

		assertEquals(Color.WHITE, PatchTimerOverlay.stateColor(growing, now));
		assertEquals(Color.GREEN, PatchTimerOverlay.stateColor(ready, now));
		assertEquals(Color.RED, PatchTimerOverlay.stateColor(dead, now));
		assertEquals(Color.ORANGE, PatchTimerOverlay.stateColor(diseased, now));
		assertEquals(Color.WHITE, PatchTimerOverlay.stateColor(picked, now));
		assertEquals("PICKED", FarmingPatchOverlay.patchTimeRemaining(picked, now));
	}

	@Test
	public void recognizesEveryPickStylePatchAction()
	{
		assertTrue(PatchTimerManager.isPickedOption("Pick"));
		assertTrue(PatchTimerManager.isPickedOption("Pick-fruit"));
		assertTrue(PatchTimerManager.isPickedOption("Pick-from"));
		assertTrue(PatchTimerManager.isPickedOption("Pick-spine"));
		assertFalse(PatchTimerManager.isPickedOption("Harvest"));
		assertFalse(PatchTimerManager.isPickedOption(null));
	}

	@Test
	public void treatsBushAndCactusHarvestsAsPicked()
	{
		assertTrue(PatchTimerManager.isPickedHarvest("Harvest", PatchType.BUSH));
		assertTrue(PatchTimerManager.isPickedHarvest("Harvest", PatchType.CACTUS));
