package com.farmingpatchadvisor;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class CompostBinCodecTest
{
	@Test
	public void decodesStandardCompostBinStates()
	{
		assertState(0, false, CompostProduct.EMPTY, CompostBinPhase.EMPTY, 0, -1);
		assertState(15, false, CompostProduct.COMPOST, CompostBinPhase.FILLING, 15, -1);
		assertState(31, false, CompostProduct.COMPOST, CompostBinPhase.PROCESSING, 15, 0);
		assertState(94, false, CompostProduct.COMPOST, CompostBinPhase.READY, 15, 2);
		assertState(47, false, CompostProduct.SUPERCOMPOST, CompostBinPhase.FILLING, 15, -1);
		assertState(95, false, CompostProduct.SUPERCOMPOST, CompostBinPhase.PROCESSING, 15, 0);
		assertState(126, false, CompostProduct.SUPERCOMPOST, CompostBinPhase.READY, 15, 2);
		assertState(176, false, CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 15, -1);
		assertState(190, false, CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 1, -1);
	}

	@Test
	public void decodesFarmingGuildBigCompostBinStates()
	{
		assertState(77, true, CompostProduct.COMPOST, CompostBinPhase.FILLING, 30, -1);
		assertState(127, true, CompostProduct.COMPOST, CompostBinPhase.PROCESSING, 30, 0);
		assertState(93, true, CompostProduct.COMPOST, CompostBinPhase.READY, 30, 2);
		assertState(175, true, CompostProduct.SUPERCOMPOST, CompostBinPhase.FILLING, 30, -1);
		assertState(97, true, CompostProduct.SUPERCOMPOST, CompostBinPhase.PROCESSING, 30, 0);
		assertState(99, true, CompostProduct.SUPERCOMPOST, CompostBinPhase.READY, 30, 2);
		assertState(176, true, CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 30, -1);
		assertState(205, true, CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 1, -1);
	}

	@Test
	public void unknownValuesDoNotCreateInventedState()
	{
		assertState(500, false, CompostProduct.UNKNOWN, CompostBinPhase.UNKNOWN, 0, -1);
		assertState(500, true, CompostProduct.UNKNOWN, CompostBinPhase.UNKNOWN, 0, -1);
	}

	private static void assertState(int value, boolean big, CompostProduct product,
		CompostBinPhase phase, int amount, int stage)
	{
		CompostBinCodec.Decoded decoded = CompostBinCodec.decode(value, big);
		assertEquals(product, decoded.getProduct());
		assertEquals(phase, decoded.getPhase());
		assertEquals(amount, decoded.getAmount());
		assertEquals(stage, decoded.getStage());
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class BankFarmRunOverlay extends OverlayPanel
{
	private static final int PANEL_WIDTH = 190;
	private static final int PANEL_GAP = 6;
	private static final int SCREEN_MARGIN = 4;
	private static final int MAX_ITEMS = 14;

	private final Client client;
	private final FarmingLoadout farmingLoadout;
	private final FarmingPatchAdvisorConfig config;
	private final FarmRunFilterState runFilterState;

	@Inject
	private BankFarmRunOverlay(Client client, FarmingLoadout farmingLoadout, FarmingPatchAdvisorConfig config,
		FarmRunFilterState runFilterState)
	{
		this.client = client;
		this.farmingLoadout = farmingLoadout;
		this.config = config;
		this.runFilterState = runFilterState;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_HIGH);
		setPreferredSize(new Dimension(PANEL_WIDTH, 0));
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showBankChecklistPanel())
		{
			return null;
		}

		Widget storage = visibleWidget(InterfaceID.Bankmain.UNIVERSE);
		boolean seedVaultOpen = false;
		if (storage == null)
		{
			storage = visibleWidget(InterfaceID.SeedVault.UNIVERSE);
			seedVaultOpen = storage != null;
		}
		if (storage == null)
		{
			return null;
		}

		FarmRunFilter selected = runFilterState.getSelected();
		List<FarmingLoadout.ChecklistItem> runChecklist = selected.isCompostOnly()
			? java.util.Collections.emptyList() : farmingLoadout.checklist(config.includeCompost(),
				config.checklistTools(), config.checklistPayments(), ChecklistPatch.selected(config));
		List<FarmingLoadout.ChecklistItem> contractChecklist = selected.isCompostOnly()
			? java.util.Collections.emptyList() : farmingLoadout.contractChecklist(config.checklistPayments());
		List<FarmingLoadout.ChecklistItem> compostChecklist = !seedVaultOpen
			&& selected.includesCompost(config.includeCompostBinsInFarmRuns())
			? farmingLoadout.compostChecklist() : java.util.Collections.emptyList();
		List<FarmingLoadout.ChecklistItem> runIncomplete = incomplete(runChecklist);
		List<FarmingLoadout.ChecklistItem> contractIncomplete = incomplete(contractChecklist);
		List<FarmingLoadout.ChecklistItem> compostIncomplete = incomplete(compostChecklist);
		List<FarmingLoadout.ChecklistItem> teleports = seedVaultOpen
			? java.util.Collections.emptyList() : farmingLoadout.teleportChecklist();

		// Always reserve room for every contract item before truncating the normal farm-run list.
		int contractDisplayed = Math.min(MAX_ITEMS, contractIncomplete.size());
		int compostDisplayed = Math.min(compostIncomplete.size(), MAX_ITEMS - contractDisplayed);
		int runDisplayed = Math.min(runIncomplete.size(), MAX_ITEMS - contractDisplayed - compostDisplayed);
		int renderedRows = (selected.isCompostOnly() ? 0 : sectionRows(runIncomplete, runDisplayed))
			+ (contractChecklist.isEmpty() ? 0 : sectionRows(contractIncomplete, contractDisplayed))
			+ (compostChecklist.isEmpty() ? 0 : sectionRows(compostIncomplete, compostDisplayed))
			+ (teleports.isEmpty() ? 0 : sectionRows(teleports, teleports.size()));
		positionNextTo(storage.getBounds(), renderedRows);
		panelComponent.getChildren().add(TitleComponent.builder()
			.text(selected.isCompostOnly() ? "Compost Run Bank List"
				: seedVaultOpen ? "Farm Run Seed List" : "Farm Run Bank List").build());
		if (!runChecklist.isEmpty() || !selected.isCompostOnly())
		{
			renderSection("Farm Run Items", runIncomplete, runDisplayed, "[x] Farm run ready");
		}
		if (!teleports.isEmpty()) { renderSection("Teleports", teleports, teleports.size(), "[x] Teleports ready"); }
		if (!compostChecklist.isEmpty())
		{
			renderSection("Compost Bins", compostIncomplete, compostDisplayed, "[x] Compost supplies ready");
		}
		if (!contractChecklist.isEmpty())
		{
			renderSection("Farming Contract", contractIncomplete, contractDisplayed,
				"[x] Contract items ready");
		}
		return super.render(graphics);
	}

	private static List<FarmingLoadout.ChecklistItem> incomplete(
		List<FarmingLoadout.ChecklistItem> checklist)
	{
		List<FarmingLoadout.ChecklistItem> incomplete = new ArrayList<>();
		for (FarmingLoadout.ChecklistItem item : checklist)
		{
			if (item.getOwned() < item.getNeeded())
			{
				incomplete.add(item);
			}
		}
		return incomplete;
	}

	private static int sectionRows(List<FarmingLoadout.ChecklistItem> items, int displayed)
	{
		return 1 + (items.isEmpty() ? 1 : displayed + (items.size() > displayed ? 1 : 0));
	}

	private void renderSection(String title, List<FarmingLoadout.ChecklistItem> items,
		int displayed, String readyText)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(title)
			.leftColor(new Color(255, 152, 31))
			.build());
		if (items.isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left(readyText)
				.leftColor(Color.GREEN)
				.build());
			return;
		}
		for (int i = 0; i < displayed; i++)
		{
			FarmingLoadout.ChecklistItem item = items.get(i);
			boolean complete = item.getOwned() >= item.getNeeded();
			panelComponent.getChildren().add(LineComponent.builder()
				.left((complete ? "[x] " : "[ ] ") + item.getName())
				.right(item.amount())
				.leftColor(complete ? Color.GREEN : item.isSeed() ? config.seedColor() : config.requiredItemColor())
				.rightColor(complete ? Color.GREEN : Color.RED)
				.build());
		}
		if (items.size() > displayed)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("+ " + (items.size() - displayed) + " more (use Farm Run filter)")
				.leftColor(Color.GRAY)
				.build());
		}
	}

	private Widget visibleWidget(int componentId)
	{
		Widget widget = client.getWidget(componentId);
		return widget == null || widget.isHidden() ? null : widget;
	}

	private void positionNextTo(Rectangle bankBounds, int rows)
	{
		int spaceLeft = bankBounds.x - PANEL_GAP;
		int spaceRight = client.getCanvasWidth() - bankBounds.x - bankBounds.width - PANEL_GAP;
		boolean useLeft;
		switch (config.bankChecklistPosition())
		{
			case LEFT:
				useLeft = true;
				break;
			case RIGHT:
				useLeft = false;
				break;
			default:
				useLeft = spaceLeft >= PANEL_WIDTH || spaceLeft > spaceRight;
		}

		int x = useLeft
			? bankBounds.x - PANEL_WIDTH - PANEL_GAP
			: bankBounds.x + bankBounds.width + PANEL_GAP;
		x = Math.max(SCREEN_MARGIN, Math.min(x, client.getCanvasWidth() - PANEL_WIDTH - SCREEN_MARGIN));
		int estimatedHeight = 28 + rows * 18;
		int y;
		switch (config.bankChecklistVerticalPosition())
		{
			case MIDDLE:
				y = bankBounds.y + (bankBounds.height - estimatedHeight) / 2;
				break;
			case BOTTOM:
				y = bankBounds.y + bankBounds.height - estimatedHeight;
				break;
			default:
				y = bankBounds.y;
		}
		y = Math.max(SCREEN_MARGIN, Math.min(y, client.getCanvasHeight() - estimatedHeight - SCREEN_MARGIN));
		setPreferredLocation(new Point(x, y));
	}
}

package com.farmingpatchadvisor;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameObject;
import net.runelite.api.MenuAction;
import net.runelite.api.ObjectComposition;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;

@Slf4j
@Singleton
final class PatchTimerManager
{
	private static final String CONFIG_GROUP = "farming-patch-advisor";
	private static final String CONFIG_KEY = "patchTimers";
	private static final Pattern GROWTH_STAGE = Pattern.compile(
		"(?i)(?:growth\\s+stage\\s*)?(?<!\\d)(\\d+)\\s*(?:/|of)\\s*(\\d+)(?!\\d)");
	private static final long INSPECTION_TIMEOUT_MILLIS = 10_000L;
	private static final int SAME_PATCH_DISTANCE = 1;
	private static final int COMPLETION_DISTANCE = 4;

	private final Client client;
	private final ConfigManager configManager;
	private final FarmingPatchAdvisorConfig config;
	private final FarmingPatchAdvisorPlugin plugin;
	private final Map<String, PatchTimer> timers = new LinkedHashMap<>();
	private final Map<String, CareState> pendingCare = new LinkedHashMap<>();
	private final Map<String, PendingCareAction> pendingCareActions = new LinkedHashMap<>();
	private final Map<String, PendingHarvest> pendingHarvests = new LinkedHashMap<>();
	private Inspection inspection;

	@Inject
	private PatchTimerManager(Client client, ConfigManager configManager, FarmingPatchAdvisorPlugin plugin,
		FarmingPatchAdvisorConfig config)
	{
		this.client = client;
		this.configManager = configManager;
		this.plugin = plugin;
		this.config = config;
	}

	synchronized void load()
	{
		unload();
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		String stored = configManager.getRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY);
		if (stored == null)
		{
			stored = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY);
			if (stored != null)
			{
				configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, stored);
				configManager.unsetConfiguration(CONFIG_GROUP, CONFIG_KEY);
			}
		}
		if (stored == null || stored.isEmpty())
		{
			return;
		}

		boolean correctedHardwoodTimer = false;
		for (String record : stored.split(";"))
		{
			try
			{
				String[] fields = record.split(",");
				WorldPoint location = new WorldPoint(
					Integer.parseInt(fields[0]), Integer.parseInt(fields[1]), Integer.parseInt(fields[2]));
				PatchType patchType = PatchType.valueOf(fields[3]);
				Crop crop = CropCatalog.findByItemId(Integer.parseInt(fields[4]));
				if (crop == null)
				{
					continue;
				}
				boolean plantedTimer = fields.length < 8 || "P".equals(fields[7]);
				int observedStage = fields.length >= 10 ? Integer.parseInt(fields[8]) : -1;
				int totalStages = fields.length >= 10 ? Integer.parseInt(fields[9]) : -1;
				boolean dead = fields.length >= 11 && "D".equals(fields[10]);
				boolean diseased = fields.length >= 11 && "S".equals(fields[10]);
				boolean picked = fields.length >= 11 && "K".equals(fields[10]);
				boolean compostApplied = fields.length >= 12 && "C".equals(fields[11]);
				boolean watered = fields.length >= 13 && "W".equals(fields[12]);
				PatchTimer timer = new PatchTimer(location, patchType, crop,
					Instant.ofEpochMilli(Long.parseLong(fields[5])),
					Instant.ofEpochMilli(Long.parseLong(fields[6])), plantedTimer, observedStage,
					 totalStages, dead, diseased, compostApplied, watered, picked);
				PatchTimer corrected = correctLegacyHardwoodTimer(timer);
				correctedHardwoodTimer |= corrected != timer;
				loadTimer(corrected);
			}
			catch (RuntimeException ex)
			{
				log.debug("Ignoring malformed farming patch timer", ex);
			}
		}
		if (correctedHardwoodTimer)
		{
			save();
		}
	}

	static PatchTimer correctLegacyHardwoodTimer(PatchTimer timer)
	{
		if (timer.getPatchType() != PatchType.HARDWOOD_TREE)
		{
			return timer;
		}
		int oldMinutes;
		switch (timer.getCrop().getName())
		{
			case "Teak sapling": oldMinutes = 5120; break;
			case "Mahogany sapling":
			case "Camphor sapling":
			case "Ironwood sapling": oldMinutes = 5760; break;
			case "Rosewood sapling": oldMinutes = 6400; break;
			default: return timer;
		}
		Duration correctedRemaining;
		long oldSeconds;
		if (timer.isPlantedTimer())
		{
			oldSeconds = Duration.ofMinutes(oldMinutes).getSeconds();
			correctedRemaining = CropGrowthTimes.forCrop(timer.getCrop());
		}
		else
		{
			int stages = timer.getTotalStages();
			int stage = timer.getObservedStage();
			if (stages < 2 || stage < 1 || stage >= stages)
			{
				return timer;
			}
			long oldStageSeconds = (oldMinutes * 60L + stages - 2L) / (stages - 1L);
			oldSeconds = oldStageSeconds * (stages - stage);
			correctedRemaining = CropGrowthTimes.maximumRemainingAtStage(timer.getCrop(), stage, stages);
		}
		if (!timer.getReadyAt().equals(timer.getPlantedAt().plusSeconds(oldSeconds)))
		{
			return timer;
		}
		return new PatchTimer(timer.getPatchLocation(), timer.getPatchType(), timer.getCrop(),
			timer.getPlantedAt(), timer.getPlantedAt().plus(correctedRemaining),
			timer.isPlantedTimer(), timer.getObservedStage(), timer.getTotalStages(),
			timer.isDead(), timer.isDiseased(), timer.isCompostApplied(), timer.isWatered(), timer.isPicked());
	}

	synchronized void unload()
	{
		timers.clear();
		pendingCare.clear();
		pendingCareActions.clear();
		pendingHarvests.clear();
		inspection = null;
	}

	synchronized Collection<PatchTimer> getTimers()
	{
		List<PatchTimer> sorted = new ArrayList<>();
		for (PatchTimer timer : timers.values())
		{
			if (isEnabledPatchLocation(timer.getPatchLocation(), timer.getPatchType()))
			{
				sorted.add(timer);
			}
		}
		sorted.sort(Comparator.comparingInt(PatchLocationCatalog::routeRank)
			.thenComparing(timer -> PatchLocationCatalog.name(timer.getPatchLocation()))
			.thenComparing(PatchTimer::getReadyAt));
		return sorted;
	}

	synchronized boolean hasDiseasedPatch(boolean secateursOnly)
	{
		for (PatchTimer timer : timers.values())
		{
			if (timer.isDiseased() && (!secateursOnly || PatchRemedy.usesSecateurs(timer.getPatchType())))
			{
				return true;
			}
		}
		return false;
	}

	synchronized PatchTimer findTimer(WorldPoint location, PatchType patchType, int maximumDistance)
	{
		return findSamePatch(location, patchType, maximumDistance);
	}

	synchronized PatchTimer findTimer(WorldPoint location, int maximumDistance)
	{
		return findNearestTimer(location, maximumDistance);
	}

	@Subscribe
	public synchronized void onMenuOptionClicked(MenuOptionClicked event)
	{
		if ("Check-health".equalsIgnoreCase(event.getMenuOption()) && isGameObjectAction(event.getMenuAction()))
		{
			markCompletedPatch(event);
			return;
		}
		if (isPickedOption(event.getMenuOption()) && isGameObjectAction(event.getMenuAction()))
		{
			markPickedPatch(event);
			return;
		}
		if (isGameObjectAction(event.getMenuAction()) && isPickedHarvest(event))
		{
			markPickedPatch(event);
			return;
		}
		if (isCompletionOption(event.getMenuOption()) && isGameObjectAction(event.getMenuAction()))
		{
			removeCompletedPatch(event);
			return;
		}

		if ("Inspect".equalsIgnoreCase(event.getMenuOption()) && isGameObjectAction(event.getMenuAction()))
		{
			beginInspection(event);
			return;
		}

		if (event.getMenuAction() != MenuAction.WIDGET_TARGET_ON_GAME_OBJECT)
		{
			return;
		}
		if (recordCareAction(event))
		{
			return;
		}

		Crop crop = CropCatalog.findByItemId(event.getItemId());
		Widget selected = client.getSelectedWidget();
		if (crop == null && selected != null)
		{
			crop = CropCatalog.findByItemId(selected.getItemId());
		}
		if (crop == null)
		{
			return;
		}
		if (!PatchClassifier.isFarmRunPatchObject(event.getId()))
		{
			return;
		}

		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classify(event.getId(), composition.getName());
		if (patchType == null || patchType != crop.getPatchType())
		{
			return;
		}

		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return;
		}
		WorldPoint anchor = plugin.getPatchAnchor(patchType, clicked);
		PatchTimer nearby = findSamePatch(anchor, patchType, SAME_PATCH_DISTANCE);
		if (nearby != null)
		{
			timers.remove(nearby.key());
			pendingHarvests.remove(nearby.key());
		}
		Instant plantedAt = Instant.now();
		CareState care = pendingCare.remove(timerKey(anchor, patchType));
		PatchTimer timer = new PatchTimer(anchor, patchType, crop, plantedAt,
			plantedAt.plus(CropGrowthTimes.forCrop(crop)), true, -1, -1, false, false,
			care != null && care.compostApplied, care != null && care.watered);
		timers.put(timer.key(), timer);
		save();
		log.debug("Started farming timer for {} at {}", crop.getName(), anchor);
	}

	synchronized void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String message = event.getMessage().replaceAll("<[^>]+>", "");
		boolean compostConfirmed = isCompostedMessage(message);
		boolean waterConfirmed = isWateredMessage(message);
		if (compostConfirmed)
		{
			confirmMostRecentCareAction(true);
		}
		if (waterConfirmed)
		{
			confirmMostRecentCareAction(false);
		}
		if (inspection == null || System.currentTimeMillis() - inspection.startedAtMillis > INSPECTION_TIMEOUT_MILLIS)
		{
			inspection = null;
			return;
		}
		if (compostConfirmed)
		{
			inspection.compostApplied = true;
		}
		if (waterConfirmed)
		{
			inspection.watered = true;
		}
		Crop mentioned = CropCatalog.findInText(message, inspection.patchType);
		if (mentioned != null)
		{
			inspection.crop = mentioned;
		}
		if (isDeadStateMessage(message))
		{
			applyUnhealthyInspection(true);
			inspection = null;
			return;
		}
		if (isDiseasedStateMessage(message))
		{
			applyUnhealthyInspection(false);
			inspection = null;
			return;
		}
		int[] growthStage = parseGrowthStage(message);
		if (growthStage != null)
		{
			inspection.currentStage = growthStage[0];
			inspection.totalStages = growthStage[1];
		}
		if (isCompletedStateMessage(message))
		{
			inspection.completed = true;
		}
		if (inspection.crop != null && (inspection.completed
			|| inspection.currentStage != null && inspection.totalStages != null))
		{
			applyInspection();
			inspection = null;
		}
	}

	synchronized void onPatchObjectSpawned(GameObject object)
	{
		if (!PatchClassifier.isFarmRunPatchObject(object.getId()))
		{
			return;
		}
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		String name = composition == null ? "" : composition.getName();
		String[] actions = composition == null ? null : composition.getActions();
		boolean dead = isDeadObjectState(name, actions);
		boolean diseased = isDiseasedObjectState(name, actions);
		boolean watered = isWateredObjectName(name);
		PatchType patchType = PatchClassifier.classifyGrowing(object.getId(), name);
		if (patchType != null && !isKnownPatchLocation(object.getWorldLocation(), patchType))
		{
			return;
		}
		if (!dead && !diseased && patchType == null)
		{
			return;
		}
		PatchTimer existing = patchType == null
			? findNearestTimer(object.getWorldLocation(), COMPLETION_DISTANCE)
			: findSamePatch(object.getWorldLocation(), patchType,
				dead || diseased ? COMPLETION_DISTANCE : SAME_PATCH_DISTANCE);
		if (existing == null)
		{
			return;
		}
		PendingHarvest harvest = pendingHarvests.get(existing.key());
		if (harvest != null && composition != null
			&& composition.getId() != harvest.objectStateId)
		{
			if (isEmptyPatchState(name, actions))
			{
				timers.remove(existing.key());
				pendingHarvests.remove(existing.key());
				save();
				return;
			}
			if (harvest.picked && !hasExplicitDeadName(name) && !diseased
				&& containsAction(actions, "Inspect")
				&& !hasHarvestAction(actions))
			{
				timers.put(existing.key(), pickedTimer(existing));
				pendingHarvests.remove(existing.key());
				save();
				return;
			}
			// Some patches briefly expose only Clear after a successful harvest action.
			// That is a harvest-state transition, not proof that the living crop died.
			if (isLiveHarvestTransition(name, actions))
			{
				dead = false;
				pendingHarvests.remove(existing.key());
			}
		}
		// A partially harvested bush/cactus can expose Clear while produce remains.
		if (harvest != null && harvest.picked && hasHarvestAction(actions)
			&& !hasExplicitDeadName(name))
		{
			dead = false;
		}
		PendingCareAction pending = pendingCareActions.get(existing.key());
		if (pending != null && pending.watered
			&& (watered || composition != null && composition.getId() != pending.objectStateId))
		{
			confirmCareAction(existing.key(), false);
			existing = timers.get(existing.key());
		}
		if (dead && existing.isPicked() && !hasExplicitDeadName(name))
		{
			return;
		}
		if (dead && !existing.isDead())
		{
			timers.put(existing.key(), unhealthyTimer(existing, true));
			save();
		}
		else if (diseased && !existing.isDiseased())
		{
			timers.put(existing.key(), unhealthyTimer(existing, false));
			save();
		}
		else if (!dead && !diseased && (existing.isDead() || existing.isDiseased()))
		{
			timers.put(existing.key(), healthyTimer(existing));
			save();
		}
		else if (watered && !existing.isWatered())
		{
			timers.put(existing.key(), withCare(existing, existing.isCompostApplied(), true));
			save();
		}
	}

	synchronized void clear()
	{
		timers.clear();
		pendingHarvests.clear();
		save();
	}

	synchronized void reset(String locationName, PatchType patchType)
	{
		timers.values().removeIf(timer -> timer.getPatchType() == patchType
			&& PatchLocationCatalog.name(timer.getPatchLocation()).equals(locationName));
		pendingHarvests.keySet().retainAll(timers.keySet());
		save();
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}
		StringBuilder value = new StringBuilder();
		for (PatchTimer timer : timers.values())
		{
			if (value.length() > 0)
			{
				value.append(';');
			}
			WorldPoint point = timer.getPatchLocation();
			value.append(point.getX()).append(',')
				.append(point.getY()).append(',')
				.append(point.getPlane()).append(',')
				.append(timer.getPatchType().name()).append(',')
				.append(timer.getCrop().getItemId()).append(',')
				.append(timer.getPlantedAt().toEpochMilli()).append(',')
				.append(timer.getReadyAt().toEpochMilli()).append(',')
				.append(timer.isPlantedTimer() ? 'P' : 'I').append(',')
				.append(timer.getObservedStage()).append(',')
				.append(timer.getTotalStages()).append(',')
				.append(timer.isDead() ? 'D' : timer.isDiseased() ? 'S' : timer.isPicked() ? 'K' : 'A').append(',')
				.append(timer.isCompostApplied() ? 'C' : 'N').append(',')
				.append(timer.isWatered() ? 'W' : 'N');
		}
		configManager.setRSProfileConfiguration(CONFIG_GROUP, CONFIG_KEY, value.toString());
	}

	private void beginInspection(MenuOptionClicked event)
	{
		if (!PatchClassifier.isFarmRunPatchObject(event.getId()))
		{
			return;
		}
		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classifyGrowing(event.getId(), composition.getName());
		if (patchType == null)
		{
			return;
		}
		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return;
		}
		WorldPoint anchor = plugin.getPatchAnchor(patchType, clicked);
		Crop crop = CropCatalog.findInText(composition.getName(), patchType);
		if (crop == null)
		{
			PatchTimer existing = findSamePatch(anchor, patchType, COMPLETION_DISTANCE);
			if (existing != null)
			{
				crop = existing.getCrop();
			}
		}
		inspection = new Inspection(anchor, patchType, crop, System.currentTimeMillis());
	}

	private void removeCompletedPatch(MenuOptionClicked event)
	{
		if (!PatchClassifier.isFarmRunPatchObject(event.getId()))
		{
			return;
		}
		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classifyGrowing(event.getId(), composition.getName());
		if (patchType == null)
		{
			return;
		}
		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return;
		}
		PatchTimer timer = findSamePatch(clicked, patchType, COMPLETION_DISTANCE);
		if (timer != null)
		{
			pendingHarvests.put(timer.key(), new PendingHarvest(composition.getId(), false));
		}
	}

	private void markPickedPatch(MenuOptionClicked event)
	{
		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classifyGrowing(event.getId(), composition.getName());
		if (patchType == null)
		{
			return;
		}
		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return;
		}
		PatchTimer timer = findSamePatch(clicked, patchType, COMPLETION_DISTANCE);
		if (timer != null)
		{
			pendingHarvests.put(timer.key(), new PendingHarvest(composition.getId(), true));
		}
	}

	private boolean isPickedHarvest(MenuOptionClicked event)
	{
		if (!"Harvest".equalsIgnoreCase(event.getMenuOption()))
		{
			return false;
		}
		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classifyGrowing(event.getId(), composition.getName());
		return isPickedHarvest(event.getMenuOption(), patchType);
	}

	private boolean recordCareAction(MenuOptionClicked event)
	{
		int itemId = event.getItemId();
		Widget selected = client.getSelectedWidget();
		if (itemId < 0 && selected != null)
		{
			itemId = selected.getItemId();
		}
		boolean compost = isCompostItem(itemId);
		boolean water = isWateringCan(itemId);
		if (!compost && !water)
		{
			return false;
		}

		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		PatchType patchType = composition == null ? null
			: PatchClassifier.classifyGrowing(event.getId(), composition.getName());
		if (patchType == null || water && !patchType.canBeWatered())
		{
			return true;
		}
		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return true;
		}
		WorldPoint anchor = plugin.getPatchAnchor(patchType, clicked);
		PatchTimer existing = findSamePatch(anchor, patchType, SAME_PATCH_DISTANCE);
		String key = existing == null ? timerKey(anchor, patchType) : existing.key();
		PendingCareAction action = pendingCareActions.computeIfAbsent(key,
			ignored -> new PendingCareAction());
		action.compostApplied |= compost;
		action.watered |= water;
		action.objectStateId = composition == null ? event.getId() : composition.getId();
		action.startedAtMillis = System.currentTimeMillis();
		return true;
	}

	private void confirmMostRecentCareAction(boolean compost)
	{
		String latestKey = null;
		long latestTime = 0;
		long now = System.currentTimeMillis();
		for (Map.Entry<String, PendingCareAction> entry : pendingCareActions.entrySet())
		{
			PendingCareAction action = entry.getValue();
			boolean matches = compost ? action.compostApplied : action.watered;
			if (matches && now - action.startedAtMillis <= 30_000L && action.startedAtMillis >= latestTime)
			{
				latestKey = entry.getKey();
				latestTime = action.startedAtMillis;
			}
		}
		if (latestKey != null)
		{
			confirmCareAction(latestKey, compost);
		}
	}

	private void confirmCareAction(String key, boolean compost)
	{
		PendingCareAction action = pendingCareActions.get(key);
		if (action == null)
		{
			return;
		}
		PatchTimer timer = timers.get(key);
		if (timer != null)
		{
			timers.put(key, withCare(timer, timer.isCompostApplied() || compost,
				timer.isWatered() || !compost));
			save();
		}
		else
		{
			CareState care = pendingCare.computeIfAbsent(key, ignored -> new CareState());
			care.compostApplied |= compost;
			care.watered |= !compost;
		}
		if (compost)
		{
			action.compostApplied = false;
		}
		else
		{
			action.watered = false;
		}
		if (!action.compostApplied && !action.watered)
		{
			pendingCareActions.remove(key);
		}
	}

	private void markCompletedPatch(MenuOptionClicked event)
	{
		ObjectComposition composition = client.getObjectDefinition(event.getId());
		if (composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		String name = composition == null ? "" : composition.getName();
		PatchType patchType = PatchClassifier.classifyGrowing(event.getId(), name);
		if (patchType == null)
		{
			return;
		}
		WorldPoint clicked = WorldPoint.fromScene(client, event.getParam0(), event.getParam1(), client.getPlane());
		if (!isEnabledPatchLocation(clicked, patchType))
		{
			return;
		}
		WorldPoint anchor = plugin.getPatchAnchor(patchType, clicked);
		PatchTimer existing = findSamePatch(anchor, patchType, COMPLETION_DISTANCE);
		Crop crop = existing == null ? CropCatalog.findInText(name, patchType) : existing.getCrop();
		if (crop == null)
		{
			return;
		}
		Instant now = Instant.now();
		PatchTimer completed = new PatchTimer(existing == null ? anchor : existing.getPatchLocation(),
			patchType, crop, existing == null ? now : existing.getPlantedAt(), now,
			existing != null && existing.isPlantedTimer(), 1, 1, false, false,
			existing != null && existing.isCompostApplied(), existing != null && existing.isWatered());
		if (existing != null)
		{
			timers.remove(existing.key());
		}
		timers.put(completed.key(), completed);
		save();
	}

	private void applyInspection()
	{
		String key = inspection.location.getX() + ":" + inspection.location.getY() + ":"
			+ inspection.location.getPlane() + ":" + inspection.patchType.name();
		PatchTimer existing = timers.get(key);
		if (existing == null)
		{
			existing = findSamePatch(inspection.location, inspection.patchType, SAME_PATCH_DISTANCE);
		}
		if (existing != null && (existing.isDead() || existing.isDiseased()))
		{
			existing = healthyTimer(existing);
			timers.put(existing.key(), existing);
		}
		Instant observedAt = Instant.now();
		if (existing != null && existing.isPlantedTimer() && !inspection.completed
			&& observedAt.isBefore(existing.getReadyAt()))
		{
			if (inspection.compostApplied || inspection.watered)
			{
				timers.put(existing.key(), withCare(existing,
					existing.isCompostApplied() || inspection.compostApplied,
					existing.isWatered() || inspection.watered));
				save();
			}
			return;
		}
		try
		{
			WorldPoint location = existing == null ? inspection.location : existing.getPatchLocation();
			if (existing != null)
			{
				timers.remove(existing.key());
			}
			int currentStage = inspection.completed ? 1 : inspection.currentStage;
			int totalStages = inspection.completed ? 1 : inspection.totalStages;
			Instant readyAt = inspection.completed ? observedAt : observedAt.plus(
				CropGrowthTimes.maximumRemainingAtStage(inspection.crop, currentStage, totalStages));
			PatchTimer timer = new PatchTimer(location, inspection.patchType, inspection.crop,
				observedAt, readyAt, false, currentStage, totalStages, false, false,
				inspection.compostApplied || existing != null && existing.isCompostApplied(),
				inspection.watered || existing != null && existing.isWatered());
			timers.put(timer.key(), timer);
			save();
		}
		catch (IllegalArgumentException ex)
		{
			log.debug("Ignoring invalid inspected farming stage", ex);
		}
	}

	private void applyUnhealthyInspection(boolean dead)
	{
		PatchTimer existing = findSamePatch(inspection.location, inspection.patchType, SAME_PATCH_DISTANCE);
		Crop crop = inspection.crop != null ? inspection.crop : existing == null ? null : existing.getCrop();
		if (crop == null)
		{
			return;
		}
		if (existing != null)
		{
			timers.put(existing.key(), unhealthyTimer(existing, dead));
		}
		else
		{
			Instant now = Instant.now();
			PatchTimer unhealthy = new PatchTimer(inspection.location, inspection.patchType, crop,
				now, now, false, -1, -1, dead, !dead);
			timers.put(unhealthy.key(), unhealthy);
		}
		save();
	}

	private static PatchTimer unhealthyTimer(PatchTimer timer, boolean dead)
	{
