	private static String timerKey(WorldPoint location, PatchType patchType)
	{
		return location.getX() + ":" + location.getY() + ":" + location.getPlane() + ":" + patchType.name();
	}

	private boolean isEnabledPatchLocation(WorldPoint location, PatchType patchType)
	{
		return isKnownPatchLocation(location, patchType)
			&& PatchLocationSelection.isEnabled(config, PatchLocationCatalog.name(location));
	}

	private static boolean isKnownPatchLocation(WorldPoint location, PatchType patchType)
	{
		return FarmRunCatalog.hasPatch(PatchLocationCatalog.name(location), patchType);
	}

	private void loadTimer(PatchTimer timer)
	{
		PatchTimer existing = findSamePatch(timer.getPatchLocation(), timer.getPatchType(), SAME_PATCH_DISTANCE);
		if (existing != null)
		{
			if (existing.getPlantedAt().isAfter(timer.getPlantedAt()))
			{
				return;
			}
			timers.remove(existing.key());
		}
		timers.put(timer.key(), timer);
	}

	private PatchTimer findSamePatch(WorldPoint location, PatchType patchType, int maximumDistance)
	{
		PatchTimer nearby = findNearbyTimer(location, patchType, maximumDistance);
		if (nearby != null || !hasSinglePatchPerLocation(patchType))
		{
			return nearby;
		}

		String locationName = PatchLocationCatalog.name(location);
		if (locationName.startsWith("Region "))
		{
			return null;
		}
		for (PatchTimer timer : timers.values())
		{
			if (timer.getPatchType() == patchType
				&& PatchLocationCatalog.name(timer.getPatchLocation()).equals(locationName))
			{
				return timer;
			}
		}
		return null;
	}

	static boolean hasSinglePatchPerLocation(PatchType patchType)
	{
		switch (patchType)
		{
			case FLOWER:
			case HERB:
			case HOPS:
			case BUSH:
			case TREE:
			case FRUIT_TREE:
			case CACTUS:
			case MUSHROOM:
			case BELLADONNA:
			case CALQUAT:
			case SPIRIT_TREE:
			case CELASTRUS:
			case REDWOOD:
			case HESPORI:
			case CRYSTAL_TREE:
				return true;
			default:
				return false;
		}
	}

	private PatchTimer findNearbyTimer(WorldPoint location, PatchType patchType, int maximumDistance)
	{
		PatchTimer nearest = null;
		int nearestDistance = maximumDistance + 1;
		for (PatchTimer timer : timers.values())
		{
			WorldPoint point = timer.getPatchLocation();
			int distance = Math.max(Math.abs(point.getX() - location.getX()),
				Math.abs(point.getY() - location.getY()));
			if (timer.getPatchType() == patchType && point.getPlane() == location.getPlane()
				&& distance < nearestDistance)
			{
				nearest = timer;
				nearestDistance = distance;
			}
		}
		return nearest;
	}

	private PatchTimer findNearestTimer(WorldPoint location, int maximumDistance)
	{
		PatchTimer nearest = null;
		int nearestDistance = maximumDistance + 1;
		for (PatchTimer timer : timers.values())
		{
			WorldPoint point = timer.getPatchLocation();
			if (point.getPlane() != location.getPlane())
			{
				continue;
			}
			int distance = Math.max(Math.abs(point.getX() - location.getX()),
				Math.abs(point.getY() - location.getY()));
			if (distance < nearestDistance)
			{
				nearest = timer;
				nearestDistance = distance;
			}
		}
		return nearest;
	}

	private static boolean isGameObjectAction(MenuAction action)
	{
		return action == MenuAction.GAME_OBJECT_FIRST_OPTION || action == MenuAction.GAME_OBJECT_SECOND_OPTION
			|| action == MenuAction.GAME_OBJECT_THIRD_OPTION || action == MenuAction.GAME_OBJECT_FOURTH_OPTION
			|| action == MenuAction.GAME_OBJECT_FIFTH_OPTION;
	}

	private static boolean isCompletionOption(String option)
	{
		String normalized = option == null ? "" : option.toLowerCase();
		return normalized.equals("harvest") || normalized.equals("clear");
	}

	static boolean isPickedOption(String option)
	{
		String normalized = option == null ? "" : option.toLowerCase();
		return normalized.startsWith("pick");
	}

	static boolean isPickedHarvest(String option, PatchType patchType)
	{
		return "Harvest".equalsIgnoreCase(option)
			&& (patchType == PatchType.BUSH || patchType == PatchType.CACTUS);
	}

	private static final class CareState
	{
		private boolean compostApplied;
		private boolean watered;
	}

	private static final class PendingCareAction
	{
		private boolean compostApplied;
		private boolean watered;
		private int objectStateId;
		private long startedAtMillis;
	}

	private static final class Inspection
	{
		private final WorldPoint location;
		private final PatchType patchType;
		private final long startedAtMillis;
		private Crop crop;
		private Integer currentStage;
		private Integer totalStages;
		private boolean completed;
		private boolean compostApplied;
		private boolean watered;

		private Inspection(WorldPoint location, PatchType patchType, Crop crop, long startedAtMillis)
		{
			this.location = location;
			this.patchType = patchType;
			this.crop = crop;
			this.startedAtMillis = startedAtMillis;
		}
	}
