			{
				compostBinManager.clear();
			}
			else
			{
				timerManager.clear();
				if (runFilterState.getSelected() == FarmRunFilter.ALL)
				{
					compostBinManager.clear();
				}
			}
		});
		actions.add(clear);
		header.add(actions);
		styleButton(editRoute);
