package com.farmingpatchadvisor;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
final class FarmRouteManager
{
	private static final String GROUP = "farming-patch-advisor";
	private final ConfigManager configManager;
	private final FarmingPatchAdvisorConfig config;
	private final FarmRunFilterState filter;

	@Inject
	FarmRouteManager(ConfigManager configManager, FarmingPatchAdvisorConfig config, FarmRunFilterState filter)
	{
		this.configManager = configManager;
		this.config = config;
		this.filter = filter;
	}

	static String key(FarmRunPatch patch)
	{
		return patch.getLocation() + "~" + patch.getPatchType().name() + "~" + patch.getName();
	}

	List<FarmRunPatch> activePatches()
	{
		return activePatches(filter.getSelected());
	}

	List<FarmRunPatch> activePatches(FarmRunFilter run)
	{
		List<FarmRunPatch> patches = availablePatches();
		String included = read("routeIncluded_" + run.name());
		if (isCustom(run) && included != null)
		{
			patches = included(patches, Arrays.asList(included.split(";")));
		}
		else
		{
			patches.removeIf(p -> !run.includes(p.getFarmRunType()));
		}
		return ordered(patches, run);
	}

	List<FarmRunPatch> availablePatches()
	{
		List<FarmRunPatch> patches = new ArrayList<>(FarmRunCatalog.patches(config));
		Set<ChecklistPatch> selected = ChecklistPatch.selected(config);
		patches.removeIf(p -> !ChecklistPatch.includes(selected, p.getPatchType()));
		return patches;
	}

	List<FarmRunPatch> defaultPatches(FarmRunFilter run)
	{
		List<FarmRunPatch> patches = availablePatches();
		patches.removeIf(p -> !run.includes(p.getFarmRunType()));
		return order(patches, Collections.emptyList());
	}

	List<FarmRunPatch> ordered(List<FarmRunPatch> patches, FarmRunFilter run)
	{
		String stored = read("routeOrder_" + run.name());
		return order(patches, stored == null ? Collections.emptyList() : Arrays.asList(stored.split(";")));
	}

	static List<FarmRunPatch> order(List<FarmRunPatch> patches, List<String> keys)
	{
		Map<String, Integer> ranks = new LinkedHashMap<>();
		for (String key : keys) { ranks.putIfAbsent(key, ranks.size()); }
		List<FarmRunPatch> result = new ArrayList<>(patches);
		result.sort(Comparator.comparing(p -> p.getFarmRunType().ordinal()));
		result.sort(Comparator.comparingInt(p -> ranks.getOrDefault(key(p), Integer.MAX_VALUE)));
		return result;
	}

	static List<FarmRunPatch> included(List<FarmRunPatch> patches, List<String> keys)
	{
		Set<String> included = new java.util.HashSet<>(keys);
		List<FarmRunPatch> result = new ArrayList<>(patches);
		result.removeIf(p -> !included.contains(key(p)));
		return result;
	}

	boolean isCustom(FarmRunFilter run) { return read("routeOrder_" + run.name()) != null; }
	String profile() { return configManager.getRSProfileKey(); }

	RouteTeleport teleport(FarmRunFilter run, FarmRunPatch patch)
	{
		String value = read("routeTeleport_" + run.name() + "_" + key(patch));
		try
		{
			RouteTeleport teleport = value == null ? RouteTeleport.NONE : RouteTeleport.valueOf(value);
			return teleport.isViableFor(patch) ? teleport : RouteTeleport.NONE;
		}
		catch (IllegalArgumentException ex) { return RouteTeleport.NONE; }
	}

	boolean save(String profile, FarmRunFilter run, List<FarmRunPatch> patches,
		Map<String, RouteTeleport> choices, boolean custom)
	{
		if (profile == null || !Objects.equals(profile, profile())) { return false; }
		String orderKey = "routeOrder_" + run.name();
		if (custom)
		{
			// Preserve disabled stops so reenabling an area does not lose its position.
			List<String> keys = new ArrayList<>();
			for (FarmRunPatch p : patches) { keys.add(key(p)); }
			String previous = read(orderKey);
			keys = mergeOrder(keys, previous == null ? Collections.emptyList() : Arrays.asList(previous.split(";")));
			configManager.setRSProfileConfiguration(GROUP, orderKey, String.join(";", keys));
			String includedKey = "routeIncluded_" + run.name();
			List<String> included = new ArrayList<>();
			for (FarmRunPatch p : patches) { included.add(key(p)); }
			String previousIncluded = read(includedKey);
			if (previousIncluded != null)
			{
				Set<String> available = new java.util.HashSet<>();
				for (FarmRunPatch p : availablePatches()) { available.add(key(p)); }
				for (String previousKey : previousIncluded.split(";"))
				{
					if (!available.contains(previousKey) && !included.contains(previousKey))
					{
						included.add(previousKey);
					}
				}
			}
			configManager.setRSProfileConfiguration(GROUP, includedKey, String.join(";", included));
		}
		else
		{
			configManager.unsetRSProfileConfiguration(GROUP, orderKey);
			configManager.unsetRSProfileConfiguration(GROUP, "routeIncluded_" + run.name());
		}
		for (Map.Entry<String, RouteTeleport> choice : choices.entrySet())
		{
			configManager.setRSProfileConfiguration(GROUP,
				"routeTeleport_" + run.name() + "_" + choice.getKey(), choice.getValue().name());
		}
		return true;
	}

	Map<RouteTeleport, Integer> requirements()
	{
		List<FarmRunPatch> active = activePatches();
		Map<String, RouteTeleport> choices = new LinkedHashMap<>();
		for (FarmRunPatch patch : active) { choices.put(key(patch), teleport(filter.getSelected(), patch)); }
		return requirements(active, choices);
	}

	static List<String> mergeOrder(List<String> visible, List<String> previous)
	{
		List<String> result = new ArrayList<>();
		int next = 0;
		for (String key : previous)
		{
			if (visible.contains(key))
			{
				if (next < visible.size()) { result.add(visible.get(next++)); }
			}
			else if (!result.contains(key)) { result.add(key); }
		}
		while (next < visible.size()) { result.add(visible.get(next++)); }
		return result;
	}

	static Map<RouteTeleport, Integer> requirements(List<FarmRunPatch> patches, Map<String, RouteTeleport> choices)
	{
		Map<RouteTeleport, Integer> requirements = new LinkedHashMap<>();
		// Multiple patches in one stop share travel when adjacent in the route.
		String previousStop = null;
		for (FarmRunPatch patch : patches)
		{
			RouteTeleport teleport = choices.getOrDefault(key(patch), RouteTeleport.NONE);
			String stop = patch.getLocation() + "~" + teleport.name();
			if (teleport != RouteTeleport.NONE && !stop.equals(previousStop))
			{
				requirements.merge(teleport, 1, teleport.consumable ? Integer::sum : Math::max);
			}
			previousStop = stop;
		}
		return requirements;
	}

	private String read(String key)
	{
		return profile() == null ? null : configManager.getRSProfileConfiguration(GROUP, key);
	}
}

package com.farmingpatchadvisor;

enum CompostBinPhase
{
	EMPTY,
	FILLING,
	PROCESSING,
	READY,
	COLLECTING,
	UNKNOWN
}

package com.farmingpatchadvisor;

final class CompostBinCodec
{
	private CompostBinCodec()
	{
	}

	static Decoded decode(int value, boolean big)
	{
		return big ? decodeBig(value) : decodeStandard(value);
	}

	private static Decoded decodeStandard(int value)
	{
		if (value == 0) return decoded(CompostProduct.EMPTY, CompostBinPhase.EMPTY, 0, -1);
		if (between(value, 1, 15)) return decoded(CompostProduct.COMPOST, CompostBinPhase.FILLING, value, -1);
		if (between(value, 16, 30)) return decoded(CompostProduct.COMPOST, CompostBinPhase.COLLECTING, 31 - value, -1);
		if (between(value, 31, 32)) return decoded(CompostProduct.COMPOST, CompostBinPhase.PROCESSING, 15, value - 31);
		if (between(value, 33, 47)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.FILLING, value - 32, -1);
		if (between(value, 48, 62)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.COLLECTING, 63 - value, -1);
		if (value == 94) return decoded(CompostProduct.COMPOST, CompostBinPhase.READY, 15, 2);
		if (between(value, 95, 96)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.PROCESSING, 15, value - 95);
		if (value == 126) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.READY, 15, 2);
		if (between(value, 129, 143)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.FILLING, value - 128, -1);
		if (between(value, 144, 158)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.COLLECTING, 159 - value, -1);
		if (between(value, 159, 160)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.PROCESSING, 15, value - 159);
		if (between(value, 176, 190)) return decoded(CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 191 - value, -1);
		return decoded(CompostProduct.UNKNOWN, CompostBinPhase.UNKNOWN, 0, -1);
	}

	private static Decoded decodeBig(int value)
	{
		if (value == 0) return decoded(CompostProduct.EMPTY, CompostBinPhase.EMPTY, 0, -1);
		if (between(value, 1, 15)) return decoded(CompostProduct.COMPOST, CompostBinPhase.FILLING, value, -1);
		if (between(value, 16, 30)) return decoded(CompostProduct.COMPOST, CompostBinPhase.COLLECTING, 46 - value, -1);
		if (between(value, 33, 47)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.FILLING, value - 32, -1);
		if (between(value, 48, 62)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.COLLECTING, 78 - value, -1);
		if (between(value, 63, 77)) return decoded(CompostProduct.COMPOST, CompostBinPhase.FILLING, value - 47, -1);
		if (between(value, 78, 92)) return decoded(CompostProduct.COMPOST, CompostBinPhase.COLLECTING, 93 - value, -1);
		if (value == 93) return decoded(CompostProduct.COMPOST, CompostBinPhase.READY, 30, 2);
		if (between(value, 97, 98)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.PROCESSING, 30, value - 97);
		if (value == 99) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.READY, 30, 2);
		if (between(value, 100, 114)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.COLLECTING, 115 - value, -1);
		if (between(value, 127, 128)) return decoded(CompostProduct.COMPOST, CompostBinPhase.PROCESSING, 30, value - 127);
		if (between(value, 129, 143)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.FILLING, value - 128, -1);
		if (between(value, 144, 158)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.COLLECTING, 174 - value, -1);
		if (between(value, 159, 160)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.PROCESSING, 30, value - 159);
		if (between(value, 161, 175)) return decoded(CompostProduct.SUPERCOMPOST, CompostBinPhase.FILLING, value - 145, -1);
		if (between(value, 176, 205)) return decoded(CompostProduct.ULTRACOMPOST, CompostBinPhase.COLLECTING, 206 - value, -1);
		if (between(value, 207, 221)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.COLLECTING, 222 - value, -1);
		if (value == 222) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.READY, 30, 2);
		if (between(value, 223, 237)) return decoded(CompostProduct.ROTTEN_TOMATO, CompostBinPhase.FILLING, value - 207, -1);
		return decoded(CompostProduct.UNKNOWN, CompostBinPhase.UNKNOWN, 0, -1);
	}

	private static boolean between(int value, int minimum, int maximum)
	{
		return value >= minimum && value <= maximum;
	}

	private static Decoded decoded(CompostProduct product, CompostBinPhase phase, int amount, int stage)
	{
		return new Decoded(product, phase, amount, stage);
	}

	static final class Decoded
	{
		private final CompostProduct product;
		private final CompostBinPhase phase;
		private final int amount;
		private final int stage;

		private Decoded(CompostProduct product, CompostBinPhase phase, int amount, int stage)
		{
			this.product = product;
			this.phase = phase;
			this.amount = amount;
			this.stage = stage;
		}

		CompostProduct getProduct() { return product; }
		CompostBinPhase getPhase() { return phase; }
		int getAmount() { return amount; }
		int getStage() { return stage; }
	}
}

