					"Lletya", "Brimhaven", "Tai Bwo Wannai", "Kastori", "Great Conch");
			case HARDWOOD_TREE:
				return 3000 + index(location, "Fossil Island", "Avium Savannah", "Anglers' Retreat");
			case HOPS:
