package com.farmingpatchadvisor;

import java.util.Locale;
import net.runelite.api.ObjectComposition;
import net.runelite.api.gameval.ObjectID;

final class PatchClassifier
{
	private static final int WEISS_HERB_PATCH = 33176;

	private PatchClassifier()
	{
	}

	static boolean isFarmRunPatchObject(int objectId)
	{
		switch (objectId)
		{
			case ObjectID.GARDEN_WHITE_TREE_PATCH:
			case ObjectID.GARDEN_WHITE_TREE_WEEDED:
			case ObjectID.GARDEN_WHITE_TREE_WEEDS_1:
			case ObjectID.GARDEN_WHITE_TREE_WEEDS_2:
			case ObjectID.GARDEN_WHITE_TREE_WEEDS_3:
			case ObjectID.GARDEN_WHITE_TREE_SEEDLING:
			case ObjectID.GARDEN_WHITE_TREE_1:
			case ObjectID.GARDEN_WHITE_TREE_2:
			case ObjectID.GARDEN_WHITE_TREE_3:
			case ObjectID.GARDEN_WHITE_TREE_FULLYGROWN:
			case ObjectID.GARDEN_WHITE_TREE_FRUIT_1:
			case ObjectID.GARDEN_WHITE_TREE_FRUIT_2:
			case ObjectID.GARDEN_WHITE_TREE_FRUIT_3:
			case ObjectID.GARDEN_WHITE_TREE_FRUIT_4:
			case ObjectID.GARDEN_WHITE_TREE_DEAD:
				return false;
			default:
				return true;
		}
	}

	static PatchType classify(String objectName)
	{
		if (objectName == null)
		{
			return null;
		}

		String name = objectName.toLowerCase(Locale.ENGLISH);
		if (name.contains("fruit tree patch"))
		{
			return PatchType.FRUIT_TREE;
		}
		if (name.contains("hardwood tree patch"))
		{
			return PatchType.HARDWOOD_TREE;
		}
		if (name.contains("crystal tree patch"))
		{
			return PatchType.CRYSTAL_TREE;
		}
		if (name.contains("spirit tree patch"))
		{
			return PatchType.SPIRIT_TREE;
		}
		if (name.contains("redwood tree patch") || name.contains("redwood patch"))
		{
			return PatchType.REDWOOD;
		}
		if (name.contains("tree patch"))
		{
			return PatchType.TREE;
		}
		if (name.contains("allotment") || name.contains("vegetable patch"))
		{
			return PatchType.ALLOTMENT;
		}
		if (name.contains("flower patch"))
		{
			return PatchType.FLOWER;
		}
		if (name.contains("herb patch"))
		{
			return PatchType.HERB;
		}
		if (name.contains("hops patch") || name.contains("hop patch"))
		{
			return PatchType.HOPS;
		}
		if (name.contains("bush patch"))
		{
			return PatchType.BUSH;
		}
		if (name.contains("potato cactus patch") || name.contains("cactus patch"))
		{
			return PatchType.CACTUS;
		}
		if (name.contains("mushroom patch") || name.contains("mushrooms patch")
			|| name.contains("bittercap patch"))
		{
			return PatchType.MUSHROOM;
		}
		if (name.contains("belladonna patch"))
		{
			return PatchType.BELLADONNA;
		}
		if (name.contains("calquat patch"))
		{
			return PatchType.CALQUAT;
		}
		if (name.contains("seaweed patch"))
		{
			return PatchType.SEAWEED;
		}
		if (name.contains("grapevine patch"))
		{
			return PatchType.GRAPEVINE;
		}
		if (name.contains("celastrus patch"))
		{
			return PatchType.CELASTRUS;
		}
		if (name.contains("hespori patch"))
		{
			return PatchType.HESPORI;
		}
		if (name.contains("anima patch"))
		{
			return PatchType.ANIMA;
		}
		if (name.contains("coral patch"))
		{
			return PatchType.CORAL;
		}
		return null;
	}

	static PatchType classify(int objectId, String objectName)
	{
		return isSpecialHerbPatchObject(objectId) ? PatchType.HERB : classify(objectName);
	}

	static PatchType classifyGrowing(String objectName)
	{
		PatchType patch = classify(objectName);
		if (patch != null)
		{
			return patch;
		}
		String name = objectName == null ? "" : objectName.toLowerCase(Locale.ENGLISH);
		if (name.contains("herb"))
		{
			return PatchType.HERB;
		}
		Crop crop = CropCatalog.findInAnyText(name);
		return crop == null ? null : crop.getPatchType();
	}

	static PatchType classifyGrowing(int objectId, String objectName)
	{
		return isSpecialHerbPatchObject(objectId) ? PatchType.HERB : classifyGrowing(objectName);
	}

	static boolean isSpecialHerbPatchObject(int objectId)
	{
		return objectId == WEISS_HERB_PATCH
			|| objectId >= ObjectID.MYARM_HERBPATCH
			&& objectId <= ObjectID.MYARM_REALPATCH_HERB4_DEAD_ACTIVE;
	}

	static boolean hasAction(ObjectComposition composition, String expected)
	{
		return composition != null && hasAction(composition.getActions(), expected);
	}

	static boolean hasAction(String[] actions, String expected)
	{
		if (actions == null)
		{
			return false;
		}
		for (String action : actions)
		{
			if (expected.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}
}

package com.farmingpatchadvisor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

final class FarmingPatchOverlay extends Overlay
{
	private static final Color CONTRACT_CLEAR_COLOR = new Color(255, 152, 31);
	private final Client client;
	private final FarmingPatchAdvisorPlugin plugin;
	private final FarmingPatchAdvisorConfig config;
	private final FarmingLoadout farmingLoadout;
	private final FarmingContractManager contractManager;
	private final PatchTimerManager timerManager;
	private final FarmRunFilterState runFilterState;
	private final FarmRouteManager routes;

	@Inject
	private FarmingPatchOverlay(Client client, FarmingPatchAdvisorPlugin plugin, FarmingPatchAdvisorConfig config,
		FarmingLoadout farmingLoadout, FarmingContractManager contractManager,
		PatchTimerManager timerManager, FarmRunFilterState runFilterState, FarmRouteManager routes)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.farmingLoadout = farmingLoadout;
		this.contractManager = contractManager;
		this.timerManager = timerManager;
		this.runFilterState = runFilterState;
		this.routes = routes;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showPatchLabels())
		{
			return null;
		}

		Set<ChecklistPatch> selectedPatches = ChecklistPatch.selected(config);
		List<FarmRunPatch> route = routes.activePatches();
		// Share recommendations within this frame, while refreshing on the next frame
		// so inventory, settings and character changes cannot leave stale results.
		EnumMap<PatchType, Crop> recommendations = new EnumMap<>(PatchType.class);
		List<PatchObject> remaining = new ArrayList<>();
		for (GameObject object : plugin.getPatchObjects())
		{
			if (object.getWorldView() == null || object.getPlane() != object.getWorldView().getPlane())
			{
				continue;
			}

			PatchType patchType = plugin.getPatchType(object);
			if (!shouldHighlight(patchType, selectedPatches, runFilterState))
			{
				continue;
			}
			Crop contractCrop = contractCrop(object, patchType);
			if (contractCrop == null && !recommendations.containsKey(patchType))
			{
				recommendations.put(patchType, farmingLoadout.recommendedCrop(patchType));
			}
			Crop crop = contractCrop != null ? contractCrop
				: recommendations.get(patchType);
			if (crop == null)
			{
				continue;
			}

			remaining.add(new PatchObject(object, patchType, crop, contractCrop != null));
		}

		while (!remaining.isEmpty())
		{
			PatchObject first = remaining.remove(remaining.size() - 1);
			List<PatchObject> group = collectConnectedPatch(first, remaining);
			PatchObject representative = group.stream().filter(patch -> patch.contractPatch)
				.findFirst().orElse(first);
			PatchTimer timer = timerManager.findTimer(representative.object.getWorldLocation(),
				representative.patchType, 4);
			Crop observedCrop = plugin.getPatchCrop(representative.object, representative.patchType);
			Crop currentCrop = observedCrop != null ? observedCrop : timer == null ? null : timer.getCrop();
			boolean clearForContract = representative.contractPatch
				&& requiresClearingForContract(currentCrop, representative.crop);
			Set<PatchTile> patchTiles = patchTiles(group);
			Area patchArea = canvasArea(patchTiles, representative.object);

			if (!patchArea.isEmpty())
			{
				Instant now = Instant.now();
				Color color = timer != null && timer.isDead() ? Color.RED
					: timer != null && timer.isDiseased() ? Color.YELLOW
						: timer != null && timer.isPicked() ? Color.WHITE
						: clearForContract ? CONTRACT_CLEAR_COLOR : config.seedColor();
				renderPatchBoundary(graphics, patchArea, patchTiles, representative.object, color);

				Rectangle bounds = patchArea.getBounds();
				List<String> lines = new ArrayList<>();
				String location = PatchLocationCatalog.name(representative.object.getWorldLocation());
				for (int i = 0; i < route.size(); i++)
				{
					if (route.get(i).getLocation().equals(location)
						&& route.get(i).getPatchType() == representative.patchType)
					{
						lines.add("Patch #" + (i + 1));
						break;
					}
				}
				if (clearForContract)
				{
					lines.add("Clear patch for contract");
					lines.add("Next: " + representative.crop.getItemName() + " x"
						+ representative.crop.getQuantity());
				}
				else
				{
					if (currentCrop != null)
					{
						lines.add("Plant: " + currentCrop.getName());
						lines.add("Time remaining: " + patchTimeRemaining(timer, now));
					}
					else
					{
						lines.add(representative.crop.getItemName() + " x" + representative.crop.getQuantity()
							+ " (Lvl " + representative.crop.getLevel() + ")");
					}
				}
				boolean growing = timer != null && !timer.isDead() && !timer.isDiseased()
					&& now.isBefore(timer.getReadyAt());
				if (growing && (timer.needsCompost() || timer.needsWater()))
				{
					StringBuilder needs = new StringBuilder("Needs: ");
					if (timer.needsCompost())
					{
						needs.append("Compost");
					}
					if (timer.needsWater())
					{
						if (needs.length() > 7)
						{
							needs.append(" + ");
						}
						needs.append("Water");
					}
					lines.add(needs.toString());
				}
				int lineHeight = graphics.getFontMetrics().getHeight();
				int textY = bounds.y + bounds.height / 2 - (lines.size() - 1) * lineHeight / 2;
				for (String line : lines)
				{
					int textX = bounds.x + (bounds.width - graphics.getFontMetrics().stringWidth(line)) / 2;
					OverlayUtil.renderTextLocation(graphics, new Point(textX, textY), line, color);
					textY += lineHeight;
				}
			}
		}
		return null;
	}

	static boolean shouldHighlight(PatchType patchType, Set<ChecklistPatch> selectedPatches,
		FarmRunFilterState runFilterState)
	{
		return patchType != null
			&& ChecklistPatch.includes(selectedPatches, patchType)
			&& runFilterState.includes(patchType);
	}

	private Crop contractCrop(GameObject object, PatchType patchType)
	{
		if (patchType == null)
		{
			return null;
		}
		FarmingContract contract = config.showFarmingContract() && config.highlightContractPatch()
			? contractManager.getContract() : null;
		if (contract != null && contract.getCrop().getPatchType() == patchType
			&& "Farming Guild".equals(PatchLocationCatalog.name(object.getWorldLocation())))
		{
			PatchTimer plantedContract = plantedContractTimer(contract);
			return plantedContract == null
				|| belongsToPlantedContractPatch(object.getWorldLocation(), plantedContract.getPatchLocation())
				? contract.getCrop() : null;
		}
		return null;
	}

	private PatchTimer plantedContractTimer(FarmingContract contract)
	{
		for (PatchTimer timer : timerManager.getTimers())
		{
			if (!timer.isDead() && timer.getCrop().equals(contract.getCrop())
				&& "Farming Guild".equals(PatchLocationCatalog.name(timer.getPatchLocation())))
			{
				return timer;
			}
		}
		return null;
	}

	static boolean belongsToPlantedContractPatch(WorldPoint objectLocation, WorldPoint timerLocation)
	{
		return objectLocation.getPlane() == timerLocation.getPlane()
			&& Math.abs(objectLocation.getX() - timerLocation.getX()) <= 1
			&& Math.abs(objectLocation.getY() - timerLocation.getY()) <= 1;
	}

	static boolean requiresClearingForContract(Crop currentCrop, Crop contractCrop)
	{
		return currentCrop != null && contractCrop != null && !contractCrop.equals(currentCrop);
	}

	static boolean usesContractGroundOutline(boolean contractPatch, Crop currentCrop)
	{
		return contractPatch && currentCrop != null;
	}

	static String patchTimeRemaining(PatchTimer timer, Instant now)
	{
		if (timer == null)
		{
			return "Inspect patch";
		}
		if (timer.isDead())
		{
			return "DEAD";
		}
		if (timer.isDiseased())
		{
			return "DISEASED";
		}
		if (timer.isPicked())
		{
			return "PICKED";
		}
		if (!now.isBefore(timer.getReadyAt()))
		{
			return "READY";
		}
		return PatchTimerOverlay.formatRemaining(Duration.between(now, timer.getReadyAt()));
	}

	private Set<PatchTile> patchTiles(List<PatchObject> group)
	{
		Set<PatchTile> tiles = new HashSet<>();
		for (PatchObject patchObject : group)
		{
			Point min = patchObject.object.getSceneMinLocation();
			Point max = patchObject.object.getSceneMaxLocation();
			if (min == null || max == null)
			{
				LocalPoint local = patchObject.object.getLocalLocation();
				tiles.add(new PatchTile(local.getSceneX(), local.getSceneY()));
				continue;
			}
			for (int x = min.getX(); x <= max.getX(); x++)
			{
				for (int y = min.getY(); y <= max.getY(); y++)
				{
					tiles.add(new PatchTile(x, y));
				}
			}
		}
		return tiles;
	}

	private Area canvasArea(Set<PatchTile> tiles, GameObject reference)
	{
		Area area = new Area();
		for (PatchTile tile : tiles)
		{
			java.awt.Polygon polygon = Perspective.getCanvasTilePoly(client,
				LocalPoint.fromScene(tile.x, tile.y, reference.getWorldView()), reference.getPlane());
			if (polygon != null)
			{
				area.add(new Area(polygon));
			}
		}
		return area;
	}

	private void renderPatchBoundary(Graphics2D graphics, Area area, Set<PatchTile> tiles,
		GameObject reference, Color color)
	{
		Color previousColor = graphics.getColor();
		Stroke previousStroke = graphics.getStroke();
		graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 25));
		graphics.fill(area);
		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(2));
		for (PatchTile tile : tiles)
		{
			if (!tiles.contains(new PatchTile(tile.x, tile.y - 1)))
			{
				drawEdge(graphics, reference, tile.x, tile.y, tile.x + 1, tile.y);
			}
			if (!tiles.contains(new PatchTile(tile.x + 1, tile.y)))
			{
				drawEdge(graphics, reference, tile.x + 1, tile.y, tile.x + 1, tile.y + 1);
			}
			if (!tiles.contains(new PatchTile(tile.x, tile.y + 1)))
			{
				drawEdge(graphics, reference, tile.x + 1, tile.y + 1, tile.x, tile.y + 1);
			}
			if (!tiles.contains(new PatchTile(tile.x - 1, tile.y)))
			{
				drawEdge(graphics, reference, tile.x, tile.y + 1, tile.x, tile.y);
			}
		}
		graphics.setStroke(previousStroke);
		graphics.setColor(previousColor);
	}

	private void drawEdge(Graphics2D graphics, GameObject reference,
		int startX, int startY, int endX, int endY)
	{
		Point start = canvasCorner(reference, startX, startY);
		Point end = canvasCorner(reference, endX, endY);
		if (start != null && end != null)
		{
			graphics.drawLine(start.getX(), start.getY(), end.getX(), end.getY());
		}
	}

	private Point canvasCorner(GameObject reference, int sceneX, int sceneY)
	{
		LocalPoint tileCenter = LocalPoint.fromScene(sceneX, sceneY, reference.getWorldView());
		return Perspective.localToCanvas(client,
			tileCenter.plus(-Perspective.LOCAL_HALF_TILE_SIZE, -Perspective.LOCAL_HALF_TILE_SIZE),
			reference.getPlane());
	}

	private static List<PatchObject> collectConnectedPatch(PatchObject first, List<PatchObject> remaining)
	{
		List<PatchObject> group = new ArrayList<>();
		ArrayDeque<PatchObject> queue = new ArrayDeque<>();
		Set<GameObject> queued = new HashSet<>();
		queue.add(first);
		queued.add(first.object);

		while (!queue.isEmpty())
		{
			PatchObject current = queue.removeFirst();
			group.add(current);
			Iterator<PatchObject> iterator = remaining.iterator();
			while (iterator.hasNext())
			{
				PatchObject candidate = iterator.next();
				if (isAdjacent(current, candidate) && queued.add(candidate.object))
				{
					queue.addLast(candidate);
					iterator.remove();
				}
			}
		}
		return group;
	}

	private static boolean isAdjacent(PatchObject first, PatchObject second)
	{
		if (first.patchType != second.patchType
			|| first.object.getWorldView() != second.object.getWorldView()
			|| first.object.getPlane() != second.object.getPlane())
		{
			return false;
		}

		Point firstMin = first.object.getSceneMinLocation();
		Point firstMax = first.object.getSceneMaxLocation();
		Point secondMin = second.object.getSceneMinLocation();
		Point secondMax = second.object.getSceneMaxLocation();
		if (firstMin != null && firstMax != null && secondMin != null && secondMax != null)
		{
			return sceneAreasTouch(firstMin, firstMax, secondMin, secondMax);
		}

		WorldPoint a = first.object.getWorldLocation();
		WorldPoint b = second.object.getWorldLocation();
		return Math.abs(a.getX() - b.getX()) <= 1 && Math.abs(a.getY() - b.getY()) <= 1;
	}

	static boolean sceneAreasTouch(Point firstMin, Point firstMax, Point secondMin, Point secondMax)
	{
		return firstMin.getX() <= secondMax.getX() + 1
			&& secondMin.getX() <= firstMax.getX() + 1
			&& firstMin.getY() <= secondMax.getY() + 1
			&& secondMin.getY() <= firstMax.getY() + 1;
	}

	private static final class PatchObject
	{
		private final GameObject object;
		private final PatchType patchType;
		private final Crop crop;
		private final boolean contractPatch;

		private PatchObject(GameObject object, PatchType patchType, Crop crop, boolean contractPatch)
		{
			this.object = object;
			this.patchType = patchType;
			this.crop = crop;
			this.contractPatch = contractPatch;
		}
	}

	private static final class PatchTile
	{
		private final int x;
		private final int y;

		private PatchTile(int x, int y)
		{
			this.x = x;
			this.y = y;
		}

		@Override
		public boolean equals(Object other)
		{
			return other instanceof PatchTile && ((PatchTile) other).x == x && ((PatchTile) other).y == y;
		}

		@Override
		public int hashCode()
		{
			return 31 * x + y;
		}
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.List;
import java.util.ArrayList;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class FarmRunChecklistOverlay extends OverlayPanel
{
	private final FarmingLoadout farmingLoadout;
	private final FarmingPatchAdvisorConfig config;
	private final Client client;
	private final FarmRunFilterState runFilterState;

	@Inject
	private FarmRunChecklistOverlay(FarmingLoadout farmingLoadout, FarmingPatchAdvisorConfig config, Client client,
		FarmRunFilterState runFilterState)
	{
		this.farmingLoadout = farmingLoadout;
		this.config = config;
		this.client = client;
		this.runFilterState = runFilterState;
		setPosition(OverlayPosition.TOP_RIGHT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showChecklistOverlay() || isStorageOpen())
		{
			return null;
		}
		FarmRunFilter selected = runFilterState.getSelected();
		List<FarmingLoadout.ChecklistItem> checklist = new ArrayList<>();
		if (!selected.isCompostOnly())
		{
			checklist.addAll(farmingLoadout.checklist(config.includeCompost(), config.checklistTools(),
				config.checklistPayments(), ChecklistPatch.selected(config)));
		}
		FontMetrics metrics = graphics.getFontMetrics();
		String title = selected.isCompostOnly() ? "Compost Run Checklist" : "Farm Run Checklist";
		int contentWidth = metrics.stringWidth(title);
		panelComponent.getChildren().add(TitleComponent.builder().text(title).build());
		int teleportStart = checklist.size();
		if (!selected.isCompostOnly())
		{
			checklist.addAll(farmingLoadout.teleportChecklist());
		}
		int compostStart = checklist.size();
		if (selected.includesCompost(config.includeCompostBinsInFarmRuns()))
		{
			checklist.addAll(farmingLoadout.compostChecklist());
		}
		int index = 0;
		for (FarmingLoadout.ChecklistItem item : checklist)
		{
			if (!selected.isCompostOnly() && index == teleportStart)
			{
				panelComponent.getChildren().add(LineComponent.builder().left("Teleports").leftColor(Color.ORANGE).build());
			}
			if (index == compostStart && compostStart < checklist.size())
			{
				panelComponent.getChildren().add(LineComponent.builder().left("Compost Bins").leftColor(Color.ORANGE).build());
			}
			index++;
			boolean complete = item.getOwned() >= item.getNeeded();
			String amount = item.amount();
			String label = (complete ? "[x] " : "[ ] ") + item.getName();
			contentWidth = Math.max(contentWidth, metrics.stringWidth(label) + metrics.stringWidth(amount) + 18);
			panelComponent.getChildren().add(LineComponent.builder()
				.left(label)
				.right(amount)
				.leftColor(complete ? Color.GREEN : (item.isSeed() ? config.seedColor() : config.requiredItemColor()))
				.rightColor(complete ? Color.GREEN : Color.RED)
				.build());
		}
		panelComponent.setPreferredSize(new Dimension(contentWidth + 20, 0));
		return super.render(graphics);
	}

	private boolean isStorageOpen()
	{
		Widget bank = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
		Widget seedVault = client.getWidget(InterfaceID.SeedVault.UNIVERSE);
		return bank != null && !bank.isHidden() || seedVault != null && !seedVault.isHidden();
	}
}

package com.farmingpatchadvisor;

import java.time.Instant;
import net.runelite.api.coords.WorldPoint;

final class PatchTimer
{
	private final WorldPoint patchLocation;
	private final PatchType patchType;
	private final Crop crop;
	private final Instant plantedAt;
	private final Instant readyAt;
	private final boolean plantedTimer;
	private final int observedStage;
	private final int totalStages;
	private final boolean dead;
	private final boolean diseased;
	private final boolean picked;
	private final boolean compostApplied;
	private final boolean watered;

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt)
	{
		this(patchLocation, patchType, crop, plantedAt, readyAt, true, -1, -1);
	}

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt,
		boolean plantedTimer, int observedStage, int totalStages)
	{
		this(patchLocation, patchType, crop, plantedAt, readyAt, plantedTimer, observedStage, totalStages, false);
	}

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt,
		boolean plantedTimer, int observedStage, int totalStages, boolean dead)
	{
		this(patchLocation, patchType, crop, plantedAt, readyAt, plantedTimer,
			observedStage, totalStages, dead, false);
	}

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt,
		boolean plantedTimer, int observedStage, int totalStages, boolean dead, boolean diseased)
	{
		this(patchLocation, patchType, crop, plantedAt, readyAt, plantedTimer, observedStage,
			totalStages, dead, diseased, false, false);
	}

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt,
		boolean plantedTimer, int observedStage, int totalStages, boolean dead, boolean diseased,
		boolean compostApplied, boolean watered)
	{
		this(patchLocation, patchType, crop, plantedAt, readyAt, plantedTimer, observedStage,
			totalStages, dead, diseased, compostApplied, watered, false);
	}

	PatchTimer(WorldPoint patchLocation, PatchType patchType, Crop crop, Instant plantedAt, Instant readyAt,
		boolean plantedTimer, int observedStage, int totalStages, boolean dead, boolean diseased,
		boolean compostApplied, boolean watered, boolean picked)
	{
		this.patchLocation = patchLocation;
		this.patchType = patchType;
		this.crop = crop;
		this.plantedAt = plantedAt;
		this.readyAt = readyAt;
		this.plantedTimer = plantedTimer;
		this.observedStage = observedStage;
		this.totalStages = totalStages;
		this.dead = dead;
		this.diseased = diseased;
		this.picked = picked;
		this.compostApplied = compostApplied;
		this.watered = watered;
	}

	String key()
	{
		return patchLocation.getX() + ":" + patchLocation.getY() + ":" + patchLocation.getPlane() + ":" + patchType.name();
	}

	WorldPoint getPatchLocation()
	{
		return patchLocation;
	}

	PatchType getPatchType()
	{
		return patchType;
	}

	Crop getCrop()
	{
		return crop;
	}

	Instant getPlantedAt()
	{
		return plantedAt;
	}

	Instant getReadyAt()
	{
		return readyAt;
	}

	boolean isPlantedTimer()
	{
		return plantedTimer;
	}

	int getObservedStage()
	{
		return observedStage;
	}

	int getTotalStages()
	{
		return totalStages;
	}

	boolean isDead()
	{
		return dead;
	}

	boolean isDiseased()
	{
		return diseased;
	}

	boolean isPicked()
	{
		return picked;
	}

	boolean isCompostApplied()
	{
		return compostApplied;
	}

	boolean isWatered()
	{
		return watered;
	}

	boolean needsCompost()
	{
		return patchType.usesCompost() && !compostApplied;
	}

	boolean needsWater()
	{
		return patchType.canBeWatered() && !watered;
	}

	int getEstimatedStage(Instant now)
	{
		if (plantedTimer || observedStage < 1 || totalStages < 2)
		{
			return observedStage;
		}
		long stageSeconds = CropGrowthTimes.stageDuration(crop, totalStages).getSeconds();
		long elapsedSeconds = Math.max(0, java.time.Duration.between(plantedAt, now).getSeconds());
		long stagesElapsed = stageSeconds == 0 ? 0 : elapsedSeconds / stageSeconds;
		return (int) Math.min(totalStages, observedStage + stagesElapsed);
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.FontMetrics;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

final class PatchTimerOverlay extends OverlayPanel
{
	private static final int MAX_CONTENT_WIDTH = 340;
	private final PatchTimerManager timerManager;
	private final FarmingPatchAdvisorConfig config;

	@Inject
	private PatchTimerOverlay(PatchTimerManager timerManager, FarmingPatchAdvisorConfig config)
	{
		this.timerManager = timerManager;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setPriority(PRIORITY_LOW);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showTimerOverlay() || timerManager.getTimers().isEmpty())
		{
			return null;
		}

		Instant now = Instant.now();
		int contentWidth = graphics.getFontMetrics().stringWidth("Farming Patch Timers");
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Farming Patch Timers")
			.build());

		for (PatchTimer timer : timerManager.getTimers())
		{
			boolean ready = !timer.isDead() && !timer.isDiseased() && !timer.isPicked()
				&& !now.isBefore(timer.getReadyAt());
			WorldPoint location = timer.getPatchLocation();
			String patch = timer.getCrop().getName() + " - " + PatchLocationCatalog.name(location);
			if (!timer.isPlantedTimer() && !timer.isDead() && !timer.isDiseased())
			{
				patch += " " + timer.getEstimatedStage(now) + "/" + timer.getTotalStages();
			}
			String remaining = timer.isDead() ? "DEAD" : timer.isDiseased() ? "DISEASED"
				: timer.isPicked() ? "PICKED"
				: ready ? "READY" : formatRemaining(Duration.between(now, timer.getReadyAt()));
			FontMetrics metrics = graphics.getFontMetrics();
			Color stateColor = stateColor(timer, now);
			int combinedWidth = metrics.stringWidth(patch) + metrics.stringWidth(remaining) + 18;
			if (combinedWidth <= MAX_CONTENT_WIDTH)
			{
				contentWidth = Math.max(contentWidth, combinedWidth);
				panelComponent.getChildren().add(LineComponent.builder()
					.left(patch).right(remaining).leftColor(stateColor)
					.rightColor(stateColor).build());
			}
			else
			{
				for (String line : wrapText(patch, metrics, MAX_CONTENT_WIDTH))
				{
					contentWidth = Math.max(contentWidth, metrics.stringWidth(line));
					panelComponent.getChildren().add(LineComponent.builder()
						.left(line).leftColor(stateColor).build());
				}
				contentWidth = Math.max(contentWidth, metrics.stringWidth(remaining));
				panelComponent.getChildren().add(LineComponent.builder().right(remaining)
					.rightColor(stateColor).build());
			}
			String remedy = PatchRemedy.forTimer(timer);
			if (remedy != null)
			{
				String remedyText = "Remedy: " + remedy;
				for (String line : wrapText(remedyText, metrics, MAX_CONTENT_WIDTH))
				{
					contentWidth = Math.max(contentWidth, metrics.stringWidth(line));
					panelComponent.getChildren().add(LineComponent.builder()
						.left(line).leftColor(Color.LIGHT_GRAY).build());
				}
			}
		}
		panelComponent.setPreferredSize(new Dimension(contentWidth + 20, 0));

		return super.render(graphics);
	}

	static Color stateColor(PatchTimer timer, Instant now)
	{
		if (timer.isDead())
		{
			return Color.RED;
		}
		if (timer.isDiseased())
		{
			return Color.ORANGE;
		}
		if (timer.isPicked())
		{
			return Color.WHITE;
		}
		return now.isBefore(timer.getReadyAt()) ? Color.WHITE : Color.GREEN;
	}

	static List<String> wrapText(String text, FontMetrics metrics, int maximumWidth)
	{
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : text.split("\\s+"))
		{
			String candidate = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && metrics.stringWidth(candidate) > maximumWidth)
			{
				lines.add(line.toString());
				line.setLength(0);
			}
			if (line.length() > 0)
			{
				line.append(' ');
			}
			line.append(word);
		}
		if (line.length() > 0)
		{
			lines.add(line.toString());
		}
		return lines;
	}

	static String formatRemaining(Duration duration)
	{
		long seconds = Math.max(0, duration.getSeconds());
		long days = seconds / 86400;
		long hours = (seconds % 86400) / 3600;
		long minutes = (seconds % 3600) / 60;
		long secs = seconds % 60;
		if (days > 0)
		{
			return String.format("%dd %02d:%02d", days, hours, minutes);
		}
		if (hours > 0)
		{
			return String.format("%d:%02d:%02d", hours, minutes, secs);
		}
		return String.format("%02d:%02d", minutes, secs);
	}
}

package com.farmingpatchadvisor;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Rectangle;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.plaf.basic.BasicScrollBarUI;
import net.runelite.client.ui.ColorScheme;

final class NarrowScrollBarUI extends BasicScrollBarUI
{
	static final int WIDTH = 8;
	private static final Color TRACK_COLOR = ColorScheme.MEDIUM_GRAY_COLOR;
	private static final Color THUMB_COLOR = ColorScheme.LIGHT_GRAY_COLOR;

	@Override
	protected void paintTrack(Graphics graphics, JComponent component, Rectangle bounds)
	{
		graphics.setColor(TRACK_COLOR);
		graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
	}

	@Override
	protected void paintThumb(Graphics graphics, JComponent component, Rectangle bounds)
	{
		if (!component.isEnabled() || bounds.isEmpty())
		{
			return;
		}
		graphics.setColor(THUMB_COLOR);
		graphics.fillRect(bounds.x + 1, bounds.y, Math.max(1, bounds.width - 2), bounds.height);
	}

	@Override
	protected Dimension getMinimumThumbSize()
	{
		return new Dimension(WIDTH - 2, 24);
	}

	@Override
	protected JButton createDecreaseButton(int orientation)
	{
		return createHiddenButton();
	}

	@Override
	protected JButton createIncreaseButton(int orientation)
	{
		return createHiddenButton();
	}

	private static JButton createHiddenButton()
	{
		JButton button = new JButton();
		Dimension size = new Dimension(0, 0);
		button.setPreferredSize(size);
		button.setMinimumSize(size);
		button.setMaximumSize(size);
		return button;
	}
}

